import{_ as t,o as a,c as i,ae as o}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"WeChat Bill Import Guide","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/02-wechat-bill-import-guide.md","filePath":"v1/en/guide/02-wechat-bill-import-guide.md"}'),l={name:"v1/en/guide/02-wechat-bill-import-guide.md"};function r(n,e,s,d,h,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="wechat-bill-import-guide" tabindex="-1">WeChat Bill Import Guide <a class="header-anchor" href="#wechat-bill-import-guide" aria-label="Permalink to &quot;WeChat Bill Import Guide&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>This guide walks you through exporting bills from WeChat and importing them into Expense Tracker: Koala (“Koala”).</p><hr><h2 id="📱-part-1-export-bills-in-wechat" tabindex="-1">📱 Part 1: Export bills in WeChat <a class="header-anchor" href="#📱-part-1-export-bills-in-wechat" aria-label="Permalink to &quot;📱 Part 1: Export bills in WeChat&quot;">​</a></h2><h3 id="step-1-open-the-bills-page" tabindex="-1">Step 1: Open the Bills page <a class="header-anchor" href="#step-1-open-the-bills-page" aria-label="Permalink to &quot;Step 1: Open the Bills page&quot;">​</a></h3><ol><li>Open WeChat</li><li>Tap <strong>Me</strong></li><li>Tap <strong>Services</strong> (or <strong>Pay</strong>)</li><li>Tap the <strong>Wallet</strong> icon (top-right)</li><li>Tap <strong>Bills</strong></li></ol><blockquote><p>📝 Note: Entry points may vary by WeChat version. If you can’t find it, try searching “账单” in WeChat.</p></blockquote><h3 id="step-2-download-a-bill-file" tabindex="-1">Step 2: Download a bill file <a class="header-anchor" href="#step-2-download-a-bill-file" aria-label="Permalink to &quot;Step 2: Download a bill file&quot;">​</a></h3><ol><li>On the Bills page, tap <strong>...</strong> or <strong>Filter</strong></li><li>In the bottom sheet, tap <strong>Download bills</strong></li><li>Choose <strong>Personal reconciliation</strong></li><li>Choose delivery method (<strong>WeChat</strong> or <strong>Email</strong>) and confirm</li><li>Select the time range (e.g. last month / last 3 months) and confirm</li></ol><blockquote><p>💡 Tips:</p><ul><li>Export up to 3 months at a time to keep the file manageable.</li><li>For longer history, export multiple files and import them one by one.</li></ul></blockquote><h3 id="step-3-complete-verification-if-prompted" tabindex="-1">Step 3: Complete verification (if prompted) <a class="header-anchor" href="#step-3-complete-verification-if-prompted" aria-label="Permalink to &quot;Step 3: Complete verification (if prompted)&quot;">​</a></h3><ol><li>Tap <strong>Next</strong></li><li>Follow WeChat’s verification steps</li><li>Wait for WeChat to generate the file</li></ol><blockquote><p>⚠️ Important:</p><ul><li>WeChat will deliver the bill file via the selected method.</li><li>If you choose email, make sure you have set up your email address in WeChat.</li></ul></blockquote><h3 id="step-4-save-the-file-to-your-device" tabindex="-1">Step 4: Save the file to your device <a class="header-anchor" href="#step-4-save-the-file-to-your-device" aria-label="Permalink to &quot;Step 4: Save the file to your device&quot;">​</a></h3><ul><li>If delivered via email: download the attachment (CSV/Excel) and save it locally.</li><li>If delivered via WeChat: download and save it to Files (if supported).</li></ul><blockquote><p>📝 Where the file usually goes:</p><ul><li>iOS: Files app → Downloads</li><li>Android: Downloads folder or WeChat folder</li></ul></blockquote><hr><h2 id="📱-part-2-import-into-expense-tracker-koala" tabindex="-1">📱 Part 2: Import into Expense Tracker: Koala <a class="header-anchor" href="#📱-part-2-import-into-expense-tracker-koala" aria-label="Permalink to &quot;📱 Part 2: Import into Expense Tracker: Koala&quot;">​</a></h2><h3 id="step-1-open-the-import-page" tabindex="-1">Step 1: Open the import page <a class="header-anchor" href="#step-1-open-the-import-page" aria-label="Permalink to &quot;Step 1: Open the import page&quot;">​</a></h3><ol><li>Open Expense Tracker: Koala</li><li>Tap <strong>Settings</strong></li><li>Find <strong>Bill Import</strong></li><li>Enter the bill import page</li></ol><h3 id="step-2-choose-the-import-source" tabindex="-1">Step 2: Choose the import source <a class="header-anchor" href="#step-2-choose-the-import-source" aria-label="Permalink to &quot;Step 2: Choose the import source&quot;">​</a></h3><ol><li>Tap <strong>Import source</strong></li><li>Select <strong>WeChat</strong></li></ol><blockquote><p>⚠️ Important: You must choose <strong>WeChat</strong>, otherwise the file cannot be parsed correctly.</p></blockquote><h3 id="step-3-pick-the-file" tabindex="-1">Step 3: Pick the file <a class="header-anchor" href="#step-3-pick-the-file" aria-label="Permalink to &quot;Step 3: Pick the file&quot;">​</a></h3><ol><li>Tap <strong>File path</strong></li><li>Select the bill file exported from WeChat</li><li>Confirm the file name is shown</li></ol><blockquote><p>📝 Supported formats:</p><ul><li>CSV (<code>.csv</code>)</li><li>Excel (<code>.xlsx</code>, <code>.xls</code>)</li></ul></blockquote><h3 id="step-4-link-a-ledger" tabindex="-1">Step 4: Link a ledger <a class="header-anchor" href="#step-4-link-a-ledger" aria-label="Permalink to &quot;Step 4: Link a ledger&quot;">​</a></h3><ol><li>Tap <strong>Linked ledger</strong></li><li>Choose the target ledger</li></ol><blockquote><p>💡 Tip: If you only have one ledger, Koala links it automatically.</p></blockquote><h3 id="step-5-parse-the-file" tabindex="-1">Step 5: Parse the file <a class="header-anchor" href="#step-5-parse-the-file" aria-label="Permalink to &quot;Step 5: Parse the file&quot;">​</a></h3><ol><li>Tap <strong>Parse</strong> (top-right)</li><li>Wait for parsing to finish</li><li>After success, Koala opens the preview page</li></ol><blockquote><p>⚠️ If parsing fails:</p><ul><li>Check the file format.</li><li>Ensure the import source is set to WeChat.</li><li>Try exporting the file again.</li></ul></blockquote><h3 id="step-6-preview-and-edit" tabindex="-1">Step 6: Preview and edit <a class="header-anchor" href="#step-6-preview-and-edit" aria-label="Permalink to &quot;Step 6: Preview and edit&quot;">​</a></h3><p>On the preview page, you can:</p><ul><li>Review records grouped by date</li><li>Tap a record to edit category, amount, time, account, tags, and notes</li><li>Long-press to delete invalid records</li><li>Batch-skip invalid records</li></ul><blockquote><p>📝 Recommendation: Always review categories and amounts before importing.</p></blockquote><h3 id="step-7-import" tabindex="-1">Step 7: Import <a class="header-anchor" href="#step-7-import" aria-label="Permalink to &quot;Step 7: Import&quot;">​</a></h3><ol><li>Confirm everything looks correct</li><li>Tap <strong>Import</strong></li><li>Wait for the import to complete</li></ol><hr><h2 id="📋-wechat-file-columns-reference" tabindex="-1">📋 WeChat file columns (reference) <a class="header-anchor" href="#📋-wechat-file-columns-reference" aria-label="Permalink to &quot;📋 WeChat file columns (reference)&quot;">​</a></h2><p>WeChat exports typically contain columns like:</p><table tabindex="0"><thead><tr><th>Column name (as exported)</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td>交易时间</td><td>Transaction time</td><td>2024-01-01 12:00:00</td></tr><tr><td>交易类型</td><td>Transaction type</td><td>微信红包 / 转账 / 消费等</td></tr><tr><td>交易对方</td><td>Counterparty</td><td>张三 / 商户名称</td></tr><tr><td>商品</td><td>Item description</td><td>午餐 / 购物等</td></tr><tr><td>收/支</td><td>Income / Expense</td><td>收入 / 支出</td></tr><tr><td>金额(元)</td><td>Amount</td><td>100.00</td></tr><tr><td>支付方式</td><td>Payment method</td><td>零钱 / 银行卡</td></tr><tr><td>当前状态</td><td>Status</td><td>支付成功/已转账/已到账</td></tr><tr><td>交易单号</td><td>Transaction ID</td><td>4200001234567890</td></tr><tr><td>商户单号</td><td>Merchant ID</td><td>1234567890</td></tr><tr><td>备注</td><td>Note</td><td>备注内容</td></tr></tbody></table><p>Excel exports have the same columns; only the file format is different.</p><hr><h2 id="⚠️-notes" tabindex="-1">⚠️ Notes <a class="header-anchor" href="#⚠️-notes" aria-label="Permalink to &quot;⚠️ Notes&quot;">​</a></h2><h3 id="_1-file-requirements" tabindex="-1">1. File requirements <a class="header-anchor" href="#_1-file-requirements" aria-label="Permalink to &quot;1. File requirements&quot;">​</a></h3><ul><li><strong>Encoding</strong>: UTF-8 is recommended</li><li><strong>Format</strong>: CSV or Excel</li><li><strong>Size</strong>: recommended under 10MB per file</li></ul><h3 id="_2-field-mapping-how-koala-imports" tabindex="-1">2. Field mapping (how Koala imports) <a class="header-anchor" href="#_2-field-mapping-how-koala-imports" aria-label="Permalink to &quot;2. Field mapping (how Koala imports)&quot;">​</a></h3><p>Koala maps the WeChat fields to Koala fields automatically:</p><ul><li>Transaction time → bill date (converted to a date string)</li><li>Income/expense → bill type</li><li>Category fields → category (may require manual adjustment)</li><li>Amount → bill amount</li><li>Payment method → account (matched by name; created if missing)</li><li>Counterparty / status / IDs / notes → bill note (combined)</li></ul><h3 id="_3-category-matching" tabindex="-1">3. Category matching <a class="header-anchor" href="#_3-category-matching" aria-label="Permalink to &quot;3. Category matching&quot;">​</a></h3><ul><li>Automatic matching may not be perfect.</li><li>Review and adjust in the preview page if needed.</li></ul><h3 id="_4-account-matching" tabindex="-1">4. Account matching <a class="header-anchor" href="#_4-account-matching" aria-label="Permalink to &quot;4. Account matching&quot;">​</a></h3><ul><li>Koala tries to match accounts by payment method.</li><li>If no matching account is found, Koala will create one.</li></ul><h3 id="_5-avoid-manual-edits-to-the-export-file" tabindex="-1">5. Avoid manual edits to the export file <a class="header-anchor" href="#_5-avoid-manual-edits-to-the-export-file" aria-label="Permalink to &quot;5. Avoid manual edits to the export file&quot;">​</a></h3><p>Do not modify the exported file (especially headers/columns). Renaming headers, deleting columns, or adding columns may cause parsing to fail.</p><hr><h2 id="🔧-faq" tabindex="-1">🔧 FAQ <a class="header-anchor" href="#🔧-faq" aria-label="Permalink to &quot;🔧 FAQ&quot;">​</a></h2><h3 id="q1-i-can-t-find-download-bills-what-should-i-do" tabindex="-1">Q1: I can’t find “Download bills”. What should I do? <a class="header-anchor" href="#q1-i-can-t-find-download-bills-what-should-i-do" aria-label="Permalink to &quot;Q1: I can’t find “Download bills”. What should I do?&quot;">​</a></h3><p>Possible reasons:</p><ol><li>Your WeChat version is too old</li><li>The entry point is different</li></ol><p>Try:</p><ul><li>Tap <strong>...</strong> on the Bills page</li><li>Look for <strong>Bills</strong> under Wallet</li><li>Search “账单导出” in WeChat</li></ul><h3 id="q2-i-didn-t-receive-the-email" tabindex="-1">Q2: I didn’t receive the email. <a class="header-anchor" href="#q2-i-didn-t-receive-the-email" aria-label="Permalink to &quot;Q2: I didn’t receive the email.&quot;">​</a></h3><p>Check:</p><ol><li>Whether an email address is linked in WeChat</li><li>Whether the email address is correct</li><li>Spam/junk folder</li><li>Try choosing “Save to Files” (if available)</li></ol><h3 id="q3-parsing-failed" tabindex="-1">Q3: Parsing failed. <a class="header-anchor" href="#q3-parsing-failed" aria-label="Permalink to &quot;Q3: Parsing failed.&quot;">​</a></h3><p>Check:</p><ol><li>File format (CSV/Excel)</li><li>Import source is WeChat</li><li>File is not corrupted</li><li>Encoding is correct (UTF-8 recommended)</li></ol><h3 id="q4-categories-look-wrong-after-import" tabindex="-1">Q4: Categories look wrong after import. <a class="header-anchor" href="#q4-categories-look-wrong-after-import" aria-label="Permalink to &quot;Q4: Categories look wrong after import.&quot;">​</a></h3><p>This can happen because WeChat’s categories may not match Koala’s categories exactly. Review and adjust categories in the preview page, or batch-edit after import.</p><h3 id="q5-can-i-import-images" tabindex="-1">Q5: Can I import images? <a class="header-anchor" href="#q5-can-i-import-images" aria-label="Permalink to &quot;Q5: Can I import images?&quot;">​</a></h3><p>Not supported.</p><h3 id="q6-how-much-history-can-i-import" tabindex="-1">Q6: How much history can I import? <a class="header-anchor" href="#q6-how-much-history-can-i-import" aria-label="Permalink to &quot;Q6: How much history can I import?&quot;">​</a></h3><p>There is no strict limit, but it’s recommended to:</p><ol><li>Import up to 3 months per file</li><li>Split large ranges into multiple files</li><li>Keep the app in the foreground during import</li></ol><hr><h2 id="💡-tips" tabindex="-1">💡 Tips <a class="header-anchor" href="#💡-tips" aria-label="Permalink to &quot;💡 Tips&quot;">​</a></h2><ol><li>Import regularly (e.g. monthly) to keep data up to date</li><li>Review categories after import for better statistics</li><li>Create common accounts ahead of time to avoid messy auto-created names</li><li>Consider backing up your data before importing</li></ol><hr><p><strong>Last updated</strong>: May 2026</p>',82)])])}const u=t(l,[["render",r]]);export{m as __pageData,u as default};
